import pg from 'pg';
function stripSsl(url) { if (!url) return url; try { const u = new URL(url); ['sslmode','sslcert','sslkey','sslrootcert'].forEach(p=>u.searchParams.delete(p)); return u.toString(); } catch { return url; } }
const client = new pg.Client({ connectionString: stripSsl(process.env.DATABASE_URL), ssl: { rejectUnauthorized: false } });
await client.connect();

const totalPts = 48;

// C-6a: check race_color values - any non-canonical values mean normalization not run
const VALID_RACE_COLOR = ['BRANCA','PRETA','PARDA','AMARELA','INDIGENA',null,''];
const rcQ = `SELECT DISTINCT race_color FROM app_patients WHERE race_color IS NOT NULL AND race_color != ''`;
const rc = await client.query(rcQ);
console.log('C6-race_color distinct values: [' + rc.rows.map(r=>r.race_color).join(',') + ']');
const invalid = rc.rows.filter(r => !VALID_RACE_COLOR.includes(r.race_color));
console.log('C6-non-canonical race_color: ' + invalid.length + ' values');
if (invalid.length > 0) { console.log('C6-WARN non-canonical: ' + invalid.map(r=>r.race_color).join(',')); } else { console.log('C6-race_color all canonical or NULL'); }

// C-6b: check maritalStatus in JSONB
const VALID_MARITAL = ['SOLTEIRO','CASADO','DIVORCIADO','VIUVO','UNIAO_ESTAVEL','SEPARADO','NAO_INFORMADO'];
const msQ = `SELECT DISTINCT payload->>'maritalStatus' as ms FROM app_patients WHERE payload->>'maritalStatus' IS NOT NULL AND payload->>'maritalStatus' != ''`;
const ms = await client.query(msQ);
console.log('C6-maritalStatus distinct: [' + ms.rows.map(r=>r.ms).join(',') + ']');
const invalidMs = ms.rows.filter(r => !VALID_MARITAL.includes(r.ms));
console.log('C6-non-canonical maritalStatus: ' + invalidMs.length + ' (should be 0 after normalization)');

// C-6c: count verify pre=post
const ptCount = await client.query('SELECT COUNT(*) as cnt FROM app_patients');
console.log('C6-COUNT-POST app_patients=' + ptCount.rows[0].cnt + ' (pre=48)');
console.log('C6-COUNT-MATCH: ' + (ptCount.rows[0].cnt === '48' ? 'PASS pre=pos' : 'WARN pre=48 pos=' + ptCount.rows[0].cnt));

await client.end();
console.log('C6-DONE');
